export function snapshot(changes: Partial<Snapshot> = {}): Snapshot {
  const p = changes.profile ?? profile();
  return {
    profile: p,
    goal: goal(p),
    logs: [],
    checks: [],
    plans: [],
    current: null,
    date: "2026-10-05",
    startDate: "2026-10-05",
    mode: "generate",
    inputRevision: 2,
    ...changes,
  };
}
